// WalletPayloadDecryptorTests.swift
// AmachHealthTests
//
// The on-device decryptor against ciphertext produced by the website's own
// encryptWithWalletKey (Fixtures/WalletDecryptorFixtures.swift, generated by
// scripts/generate-decryptor-fixtures.ts), plus the vault key and bucket name.

import XCTest
@testable import AmachHealth

final class WalletPayloadDecryptorTests: XCTestCase {

    private let key = WalletDecryptorFixtures.encryptionKey

    func test_decrypts_every_website_fixture() throws {
        XCTAssertFalse(WalletDecryptorFixtures.cases.isEmpty)
        for fixture in WalletDecryptorFixtures.cases {
            let bytes = Data(fixture.objectText.utf8)
            let plain = try WalletPayloadDecryptor.decrypt(objectBytes: bytes, passphrase: key)
            XCTAssertEqual(plain, fixture.plaintext, fixture.name)
        }
    }

    func test_decrypts_without_0x_prefix() throws {
        let fixture = try XCTUnwrap(WalletDecryptorFixtures.cases.first)
        let bare = String(fixture.objectText.dropFirst(2))
        XCTAssertEqual(try WalletPayloadDecryptor.decrypt(objectText: bare, passphrase: key), fixture.plaintext)
    }

    func test_decryptJSON_parses_wrapped_value() throws {
        let fixture = try XCTUnwrap(WalletDecryptorFixtures.cases.first { $0.name == "unicode" })
        let value = try WalletPayloadDecryptor.decryptJSON(objectBytes: Data(fixture.objectText.utf8), passphrase: key)
        let dict = try XCTUnwrap(value as? [String: Any])
        XCTAssertEqual(dict["note"] as? String, "Café — 睡眠 💤")
        XCTAssertEqual(dict["value"] as? Double, 42.5)
    }

    func test_wrong_key_fails() {
        let fixture = WalletDecryptorFixtures.cases[2]
        let wrong = String(repeating: "0", count: 64)
        XCTAssertThrowsError(try WalletPayloadDecryptor.decrypt(objectText: fixture.objectText, passphrase: wrong))
    }

    func test_rejects_non_ciphertext() {
        XCTAssertThrowsError(try WalletPayloadDecryptor.decrypt(objectText: "0xnot base64!", passphrase: key)) { error in
            XCTAssertEqual(error as? WalletPayloadDecryptor.DecryptError, .invalidBase64)
        }
        let noHeader = "0x" + Data(repeating: 1, count: 32).base64EncodedString()
        XCTAssertThrowsError(try WalletPayloadDecryptor.decrypt(objectText: noHeader, passphrase: key)) { error in
            XCTAssertEqual(error as? WalletPayloadDecryptor.DecryptError, .missingSaltHeader)
        }
        XCTAssertThrowsError(try WalletPayloadDecryptor.decrypt(objectBytes: Data([0xFF, 0xFE]), passphrase: key)) { error in
            XCTAssertEqual(error as? WalletPayloadDecryptor.DecryptError, .notUTF8)
        }
    }

    func test_truncated_ciphertext_fails() throws {
        let fixture = try XCTUnwrap(WalletDecryptorFixtures.cases.last)
        var blob = try XCTUnwrap(Data(base64Encoded: String(fixture.objectText.dropFirst(2))))
        blob.removeLast(5)
        XCTAssertThrowsError(try WalletPayloadDecryptor.decrypt(objectText: blob.base64EncodedString(), passphrase: key))
    }

    func test_evpBytesToKey_matches_openssl() {
        // openssl enc -aes-256-cbc -md md5 -P -S 0102030405060708 -k password
        let (k, iv) = WalletPayloadDecryptor.evpBytesToKey(passphrase: Array("password".utf8), salt: [1, 2, 3, 4, 5, 6, 7, 8])
        XCTAssertEqual(hex(k), "e7b0971e52ca5cc8d0539fb3412f6316f7ba2e6ee293d9f3457b99436b51ce02")
        XCTAssertEqual(hex(iv), "8d450e2ed75a84a923d4eac9fe49226b")
    }

    // MARK: - Bucket name and vault key

    func test_bucket_name_matches_website_generateBucketName() {
        XCTAssertEqual(
            StorjBucketName.make(walletAddress: WalletDecryptorFixtures.walletAddress, encryptionKey: key),
            WalletDecryptorFixtures.expectedBucket
        )
        XCTAssertEqual(
            StorjBucketName.make(walletAddress: WalletDecryptorFixtures.walletAddress.uppercased(), encryptionKey: key),
            WalletDecryptorFixtures.expectedBucket,
            "address is lowercased first"
        )
        XCTAssertEqual(
            StorjBucketName.make(walletAddress: WalletDecryptorFixtures.walletAddress, encryptionKey: key, prefix: "amach-test"),
            WalletDecryptorFixtures.expectedBucketCustomPrefix
        )
    }

    func test_vault_key_is_hkdf_sha256_with_amach_info() throws {
        let walletKey = WalletEncryptionKey(walletAddress: WalletDecryptorFixtures.walletAddress, encryptionKey: key,
                                            signature: "0x", timestamp: 0)
        let vaultKey = try LocalVaultKey(walletKey: walletKey)
        // RFC 5869 HKDF-SHA256(ikm = key bytes, salt = empty, info = "amach-local-db-v1", L = 32),
        // computed independently with Python's hmac module.
        XCTAssertEqual(hex([UInt8](vaultKey.rawBytes)), "9cde7c976d5e8f635bfdfda00f0a5b7c0edecb482fe04ca936ee7acd7586116f")
        XCTAssertEqual(vaultKey.fileIdentifier.count, 16)
        XCTAssertNotEqual(vaultKey.keyCheck, vaultKey.fileIdentifier)
    }

    func test_different_wallet_keys_give_different_vault_files() throws {
        let a = try LocalVaultKey(walletKey: WalletEncryptionKey(walletAddress: "0xa", encryptionKey: key, signature: "", timestamp: 0))
        let b = try LocalVaultKey(walletKey: .testFixture())
        XCTAssertNotEqual(a.fileIdentifier, b.fileIdentifier)
    }

    private func hex(_ bytes: [UInt8]) -> String { bytes.map { String(format: "%02x", $0) }.joined() }
}
